Point3D GetBoxCenter(const BoundingBox3D& box) {
    return Point3D{
        (box.Min.x + box.Max.x) / 2.0f,
        (box.Min.y + box.Max.y) / 2.0f,
        (box.Min.z + box.Max.z) / 2.0f
    };
